                .map_err(serde::de::Error::custom),
            ReleaseOperationRoleWire::Tag => Ok(Self::Tag),
            ReleaseOperationRoleWire::ForgeRelease => Ok(Self::ForgeRelease),
        }
    }
}

impl ReleaseOperationRole {
    fn discriminator(&self) -> u8 {
        match self {
            Self::RegistryPublish { .. } => 0,
            Self::Tag => 1,
            Self::ForgeRelease => 2,
        }
    }

    fn registry_key(&self) -> Option<&RegistryKey> {
        match self {
            Self::RegistryPublish { registry_key } => Some(registry_key),
            Self::Tag | Self::ForgeRelease => None,
        }
    }
}

/// Exact identity for one durable release operation.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseOperationId {
    pub package: ReleasePackageId,
    pub role: ReleaseOperationRole,
    pub version: Version,
}

impl ReleaseOperationId {
    pub fn registry_publish(
        package: ReleasePackageId,
        version: Version,
        registry_key: impl Into<String>,
    ) -> Result<Self, ReleaseOperationError> {
        let registry_key = validated_registry_key(registry_key.into())?;
        Ok(Self {
            package,
            role: ReleaseOperationRole::RegistryPublish { registry_key },
            version,
        })
    }

    pub fn tag(package: ReleasePackageId, version: Version) -> Self {
        Self {
            package,
            role: ReleaseOperationRole::Tag,
            version,
        }
    }

    pub fn forge_release(package: ReleasePackageId, version: Version) -> Self {
        Self {
            package,
            role: ReleaseOperationRole::ForgeRelease,
            version,
        }
    }
}

impl PartialOrd for ReleaseOperationId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ReleaseOperationId {
    fn cmp(&self, other: &Self) -> Ordering {
        (
            self.package.ecosystem().prefix(),
            self.package.name(),
            self.role.discriminator(),
            self.version.render(),
            self.role.registry_key().map(RegistryKey::as_str).unwrap_or(""),
        )
            .cmp(&(
                other.package.ecosystem().prefix(),
                other.package.name(),
                other.role.discriminator(),
                other.version.render(),
                other.role.registry_key().map(RegistryKey::as_str).unwrap_or(""),
            ))
    }
}

/// One canonical DAG node in a durable release intent.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseOperation {
    id: ReleaseOperationId,
    prerequisites: Vec<ReleaseOperationId>,
}

impl ReleaseOperation {
    pub fn registry_publish(
        package: ReleasePackageId,
        version: Version,
        registry_key: impl Into<String>,
        prerequisites: Vec<ReleaseOperationId>,
    ) -> Result<Self, ReleaseOperationError> {
        Self::new(
            ReleaseOperationId::registry_publish(package, version, registry_key)?,
            prerequisites,
        )
    }

    pub fn tag(
        package: ReleasePackageId,
        version: Version,
        prerequisites: Vec<ReleaseOperationId>,
    ) -> Result<Self, ReleaseOperationError> {
        Self::new(ReleaseOperationId::tag(package, version), prerequisites)
    }

    pub fn forge_release(
        package: ReleasePackageId,
        version: Version,
        prerequisites: Vec<ReleaseOperationId>,
    ) -> Result<Self, ReleaseOperationError> {
        Self::new(ReleaseOperationId::forge_release(package, version), prerequisites)
    }

    pub fn new(
        id: ReleaseOperationId,
        mut prerequisites: Vec<ReleaseOperationId>,
    ) -> Result<Self, ReleaseOperationError> {
        prerequisites.sort();
        if prerequisites.iter().any(|prerequisite| prerequisite == &id) {
            return Err(ReleaseOperationError::SelfPrerequisite { id: Box::new(id) });
        }
        if prerequisites.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(ReleaseOperationError::DuplicatePrerequisite { id: Box::new(id) });
        }
        Ok(Self { id, prerequisites })
    }

    pub fn id(&self) -> &ReleaseOperationId {
        &self.id
    }

    pub fn prerequisites(&self) -> &[ReleaseOperationId] {
        &self.prerequisites
    }
}

/// Errors in exact release-operation construction.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseOperationError {
    #[error("registry key `{raw}` is malformed")]
    MalformedRegistryKey { raw: String },
    #[error("release operation `{id:?}` cannot require itself")]
    SelfPrerequisite { id: Box<ReleaseOperationId> },
    #[error("release operation `{id:?}` has duplicate prerequisites")]
    DuplicatePrerequisite { id: Box<ReleaseOperationId> },
}

fn validated_registry_key(raw: String) -> Result<RegistryKey, ReleaseOperationError> {
    if raw.is_empty()
        || raw.len() > 128
        || !raw
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(ReleaseOperationError::MalformedRegistryKey { raw });
    }
    Ok(RegistryKey(raw))
}

/// An immutable, canonical authorization intent. Graph owns its construction.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseIntentV1 {
    pub schema_version: u8,
    pub snapshot: ReleaseInputSnapshotV1,
    pub trust_profile: ExecutionTrustProfileV1,
    pub operations: Vec<ReleaseOperation>,
    digest: IntentDigest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseIntentV1Wire {
    schema_version: u8,
    snapshot: ReleaseInputSnapshotV1,
    trust_profile: ExecutionTrustProfileV1,
    operations: Vec<ReleaseOperation>,
    digest: IntentDigest,
}

impl<'de> Deserialize<'de> for ReleaseIntentV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseIntentV1Wire::deserialize(deserializer)?;
        if wire.schema_version != Self::SCHEMA_VERSION
            || wire.snapshot.schema_version != ReleaseInputSnapshotV1::SCHEMA_VERSION
        {
            return Err(serde::de::Error::custom("unsupported release intent schema version"));
        }
        if wire.snapshot.components.windows(2).any(|pair| pair[0] >= pair[1]) {
            return Err(serde::de::Error::custom("release input components are not canonical"));
        }
        let intent = Self::new(wire.snapshot, wire.trust_profile, wire.operations).map_err(serde::de::Error::custom)?;
        if intent.digest != wire.digest {
            return Err(serde::de::Error::custom(
                "release intent digest does not match canonical content",
            ));
        }
        Ok(intent)
    }
}

impl ReleaseIntentV1 {
    pub const SCHEMA_VERSION: u8 = 1;

    pub fn new(
        snapshot: ReleaseInputSnapshotV1,
        trust_profile: ExecutionTrustProfileV1,
        operations: Vec<ReleaseOperation>,
    ) -> Result<Self, ReleaseIntentError> {
        validate_operations(&operations)?;
        let digest = digest_intent(&snapshot, trust_profile, &operations);
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            snapshot,
            trust_profile,
            operations,
            digest,
        })
    }

    pub fn digest(&self) -> &IntentDigest {
        &self.digest
    }
}

fn digest_intent(
    snapshot: &ReleaseInputSnapshotV1,
    trust_profile: ExecutionTrustProfileV1,
    operations: &[ReleaseOperation],
) -> IntentDigest {
    let mut transcript = CanonicalTranscript::intent_v1();
    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
    transcript.push_str("snapshot", snapshot.digest().as_str());
    transcript.push_str(
        "trust-profile",
        match trust_profile {
            ExecutionTrustProfileV1::GitCommit => "git-commit",
            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
        },
    );
    for operation in operations {
        transcript.push_str("operation", &operation_id_text(&operation.id));
        for prerequisite in &operation.prerequisites {
            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
        }
    }
    IntentDigest::from_transcript(&transcript)
}

fn operation_id_text(id: &ReleaseOperationId) -> String {
    let role = match &id.role {
        ReleaseOperationRole::RegistryPublish { registry_key } => format!("publish:{}", registry_key.as_str()),
        ReleaseOperationRole::Tag => "tag".to_string(),
        ReleaseOperationRole::ForgeRelease => "forge-release".to_string(),
    };
    format!("{}|{}|{}", id.package, role, id.version.render())
}

fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
    if operations.windows(2).any(|pair| pair[0].id >= pair[1].id) {
        if operations.windows(2).any(|pair| pair[0].id == pair[1].id) {
            return Err(ReleaseIntentError::DuplicateOperation {
                id: Box::new(
                    operations
                        .windows(2)
                        .find(|pair| pair[0].id == pair[1].id)
                        .expect("duplicate window exists")[0]
                        .id
                        .clone(),
                ),
            });
        }
        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
    }
    let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
    for operation in operations {
        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
                id: Box::new(operation.id.clone()),
            });
        }
        for prerequisite in &operation.prerequisites {
            if prerequisite == &operation.id {
                return Err(ReleaseIntentError::SelfPrerequisite {
                    id: Box::new(operation.id.clone()),
                });
            }
            if !ids.contains(prerequisite) {
                return Err(ReleaseIntentError::UnknownPrerequisite {
                    id: Box::new(operation.id.clone()),
                    prerequisite: Box::new(prerequisite.clone()),
                });
            }
        }
    }
    let edges: BTreeMap<_, _> = operations
        .iter()
        .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
        .collect();
    let mut visiting = BTreeSet::new();
    let mut visited = BTreeSet::new();
    for id in edges.keys() {
        if visit(id, &edges, &mut visiting, &mut visited) {
            return Err(ReleaseIntentError::Cycle {
                id: Box::new(id.clone()),
            });
        }
    }
    Ok(())
}

fn visit(
    id: &ReleaseOperationId,
    edges: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
    visiting: &mut BTreeSet<ReleaseOperationId>,
    visited: &mut BTreeSet<ReleaseOperationId>,
) -> bool {
    if visited.contains(id) {
        return false;
    }
    if !visiting.insert(id.clone()) {
        return true;
    }
    let has_cycle = edges.get(id).is_some_and(|prerequisites| {
        prerequisites
            .iter()
            .any(|prerequisite| visit(prerequisite, edges, visiting, visited))
    });
    visiting.remove(id);
    visited.insert(id.clone());
    has_cycle
}

/// Validation failure for a durable intent DAG.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseIntentError {
    #[error("release operations are not in canonical order")]
    NonCanonicalOperationOrder,
    #[error("duplicate release operation `{id:?}`")]
    DuplicateOperation { id: Box<ReleaseOperationId> },
    #[error("prerequisites for `{id:?}` are not in canonical order")]
    NonCanonicalPrerequisiteOrder { id: Box<ReleaseOperationId> },
    #[error("release operation `{id:?}` requires unknown operation `{prerequisite:?}`")]
    UnknownPrerequisite {
        id: Box<ReleaseOperationId>,
        prerequisite: Box<ReleaseOperationId>,
    },
    #[error("release operation `{id:?}` requires itself")]
    SelfPrerequisite { id: Box<ReleaseOperationId> },
    #[error("release operation DAG contains a cycle at `{id:?}`")]
    Cycle { id: Box<ReleaseOperationId> },
}

/// A terminal outcome safe to persist in a receipt. No arbitrary error text is durable.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum OperationOutcome {
    Published,
    AlreadySatisfied,
    Failed,
    Blocked,
}

/// Crash-safe state for an intent-bound execution. Pending and Attempting are nonterminal.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseExecutionStateV1 {
    pub schema_version: u8,
    intent_digest: IntentDigest,
    operations: BTreeMap<ReleaseOperationId, OperationState>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum OperationState {
    Pending,
    Attempting,
    Published,
    AlreadySatisfied,
    Failed,
    Blocked,
}

impl ReleaseExecutionStateV1 {
    pub const SCHEMA_VERSION: u8 = 1;

    pub fn pending(intent_digest: IntentDigest, ids: &[ReleaseOperationId]) -> Self {
        Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest,
            operations: ids.iter().cloned().map(|id| (id, OperationState::Pending)).collect(),
        }
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    pub fn mark_attempting(&mut self, id: &ReleaseOperationId) -> Result<(), ReleaseStateError> {
        let state = self
            .operations
            .get_mut(id)
            .ok_or_else(|| ReleaseStateError::UnknownOperation {
                id: Box::new(id.clone()),
            })?;
        if *state != OperationState::Pending {
            return Err(ReleaseStateError::InvalidTransition {
                id: Box::new(id.clone()),
                from: *state,
            });
        }
        *state = OperationState::Attempting;
        Ok(())
    }

    pub fn mark_terminal(
        &mut self,
        id: &ReleaseOperationId,
        outcome: OperationOutcome,
    ) -> Result<(), ReleaseStateError> {
        let state = self
            .operations
            .get_mut(id)
            .ok_or_else(|| ReleaseStateError::UnknownOperation {
                id: Box::new(id.clone()),
            })?;
        if *state != OperationState::Attempting {
            return Err(ReleaseStateError::InvalidTransition {
                id: Box::new(id.clone()),
                from: *state,
            });
        }
        *state = match outcome {
            OperationOutcome::Published => OperationState::Published,
            OperationOutcome::AlreadySatisfied => OperationState::AlreadySatisfied,
            OperationOutcome::Failed => OperationState::Failed,
            OperationOutcome::Blocked => OperationState::Blocked,
        };
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseStateError {
    #[error("release state does not contain operation `{id:?}`")]
    UnknownOperation { id: Box<ReleaseOperationId> },
    #[error("operation `{id:?}` cannot transition from {from:?}")]
    InvalidTransition {
        id: Box<ReleaseOperationId>,
        from: OperationState,
    },
}

/// A terminal receipt derived only from a complete execution state.
//! Graph-owned construction and validation of durable release intents.
//!
//! The caller supplies an already-resolved selection.  This deliberately does
//! not call `plan_version` or `plan_publish`: received-intent validation must
//! compare an approval, not silently make a fresh planning decision.

use std::collections::{BTreeMap, BTreeSet};

use callisto_model::{
    CanonicalTranscript, CommandRunner, ExecutionTrustProfileV1, PublishTarget, ReleaseInputComponentV1,
    ReleaseInputSnapshotV1, ReleaseIntentV1, ReleaseOperation, ReleaseOperationId, ReleasePackageId,
    SemanticInputDigest, SourceIdentity, Version,
};
use callisto_vcs::GitDataSource;

use crate::{DependencyResolver, GraphError, Workspace};

/// Exact package/version values selected by a preceding release decision.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ReleaseSelection {
    versions: BTreeMap<ReleasePackageId, Version>,
}

impl ReleaseSelection {
    pub fn new(versions: BTreeMap<ReleasePackageId, Version>) -> Self {
        Self { versions }
    }

    pub fn versions(&self) -> &BTreeMap<ReleasePackageId, Version> {
        &self.versions
    }
}

/// In-memory proof that an intent was rebuilt against one workspace.
///
/// Its private field, lack of `Clone`, and lack of serialization are
/// intentional: callers cannot forge or transfer this capability.
#[derive(Debug)]
pub struct ValidatedReleaseIntent {
    intent: ReleaseIntentV1,
}

impl ValidatedReleaseIntent {
    pub fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }
}

/// Builds a canonical intent using read-only workspace observation only.
pub fn build_release_intent<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    match trust_profile {
        ExecutionTrustProfileV1::GitCommit => {
            let git = ws.git_access();
            if !git.has_clean_detached_head()? || source != (SourceIdentity::GitCommit { sha: git.head_sha()? }) {
                return Err(GraphError::ReleaseIntentStale);
            }
        }
        // A hermetic release needs a closed-root observer. It is safer to
        // reject this profile until graph owns that complete observation than
        // to accidentally bless a Git-derived projection as hermetic.
        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
    }
    let (snapshot, operations) = derive_release_inputs(ws, selection, source)?;
    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)
}

/// Rebuilds the snapshot and exact DAG from the supplied workspace. This does
/// not invoke either planner and does not execute the rebuilt graph.
pub fn validate_release_intent<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent, GraphError> {
    // A received source identity is evidence to check, never input trusted by
    // validation.  Hermetic verification needs its own closed-root observer;
    // until that exists it cannot obtain this Git-backed capability.
    let observed_source = match received.trust_profile {
        ExecutionTrustProfileV1::GitCommit => SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha()?,
        },
        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
    };
    let expected = build_release_intent(ws, selection, observed_source, received.trust_profile)?;
    if expected != received {
        return Err(GraphError::ReleaseIntentStale);
    }
    Ok(ValidatedReleaseIntent { intent: received })
}

fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
    let mut components = Vec::new();
    let mut component_kinds = BTreeSet::new();
    let mut selected = BTreeMap::new();

    for package in ws.graph.packages() {
        for ecosystem in package
            .canonical_manifests()
            .map(|m| m.ecosystem())
            .collect::<BTreeSet<_>>()
        {
            let id =
                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
            if let Some(version) = selection.versions().get(&id) {
                selected.insert(id, (package, version.clone()));
            }
        }
    }
    for id in selection.versions().keys() {
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    // These policies affect release selection/DAG policy. Store a digest only.
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.cascade",
        format!("{:?}", ws.config.cascade),
    );
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.validation",
        format!("{:?}", ws.config.validation),
    );
    push_component(
        &mut components,
        &mut component_kinds,
        "policy.groups",
        format!("{:?}", ws.config.groups),
    );
    for (key, registry) in &ws.config.registries {
        let binding = registry
            .url
            .as_deref()
            .map(|url| normalize_registry_url(key.as_str(), url))
            .transpose()?
            .unwrap_or_else(|| "default".to_string());
        push_component(
            &mut components,
            &mut component_kinds,
            format!("registry-binding:{}", key.as_str()),
            format!("{}:{binding}", registry.kind.prefix()),
        );
    }

    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
    for (id, (package, version)) in selected {
        let mut package_input = CanonicalTranscript::semantic_input_v1();
        package_input.push_str("package.id", &id.to_string());
        package_input.push_str("package.version", version.render());
        for manifest in &package.manifests {
            let bytes = std::fs::read(ws.root.join(&manifest.path)).map_err(|error| GraphError::ReleaseInputRead {
                path: manifest.path.clone(),
                message: error.to_string(),
            })?;
            package_input.push_str("manifest.path", &manifest.path.display().to_string());
            package_input.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
            package_input.push_str("manifest.role", &format!("{:?}", manifest.role));
            package_input.push_str("manifest.format", &format!("{:?}", manifest.format));
        }
        package_input.push_str("package.trigger", &format!("{:?}", package.release_trigger));
        package_input.push_str(
            "package.tag",
            &package
                .tag_template
                .as_ref()
                .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
        );

        let mut publishes = Vec::new();
        let mut has_target = false;
        let mut has_forge_release = false;
        for target in &package.publish_to {
            match target {
                PublishTarget::None => {}
                PublishTarget::GitHubRelease => {
                    has_target = true;
                    has_forge_release = true;
                    package_input.push_str("package.target", "github-release");
                }
                _ => {
                    has_target = true;
                    package_input.push_str("package.target", &target_fingerprint(target)?);
                    if target.ecosystem() == Some(id.ecosystem()) {
                        if let Some(key) = target.registry_key() {
                            let operation = ReleaseOperation::registry_publish(
                                id.clone(),
                                version.clone(),
                                key.as_str().to_string(),
                                Vec::new(),
                            )
                            .map_err(|_error| GraphError::ReleaseIntentStale)?;
                            publishes.push(operation.id().clone());
                            operations.insert(operation.id().clone(), operation);
                        }
                    }
                }
            }
        }
        push_fingerprint(
            &mut components,
            &mut component_kinds,
            format!("package:{id}"),
            SemanticInputDigest::from_transcript(&package_input),
        );
        if has_target {
            publishes.sort();
            let tag = ReleaseOperation::tag(id.clone(), version.clone(), publishes)
                .map_err(|_error| GraphError::ReleaseIntentStale)?;
            let tag_id = tag.id().clone();
            operations.insert(tag_id.clone(), tag);
            if has_forge_release {
                let forge = ReleaseOperation::forge_release(id, version, vec![tag_id])
                    .map_err(|_error| GraphError::ReleaseIntentStale)?;
                operations.insert(forge.id().clone(), forge);
            }
        }
    }
    Ok((
        ReleaseInputSnapshotV1::new(source, components),
        operations.into_values().collect(),
    ))
}

fn push_component(
    components: &mut Vec<ReleaseInputComponentV1>,
    kinds: &mut BTreeSet<String>,
    kind: impl Into<String>,
    value: String,
) {
    let kind = kind.into();
    assert!(
        kinds.insert(kind.clone()),
        "release snapshot component kinds must be unique"
    );
    components.push(ReleaseInputComponentV1 {
        kind,
        fingerprint: digest_text("component", &value),
    });
}

fn push_fingerprint(
    components: &mut Vec<ReleaseInputComponentV1>,
    kinds: &mut BTreeSet<String>,
    kind: impl Into<String>,
    fingerprint: SemanticInputDigest,
) {
    let kind = kind.into();
    assert!(
        kinds.insert(kind.clone()),
        "release snapshot component kinds must be unique"
    );
    components.push(ReleaseInputComponentV1 { kind, fingerprint });
}

fn digest_text(tag: &str, text: &str) -> SemanticInputDigest {
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str(tag, text);
    SemanticInputDigest::from_transcript(&transcript)
}

fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_bytes(tag, bytes);
    SemanticInputDigest::from_transcript(&transcript)
}

fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
    let endpoint = |registry, value: Option<&String>| {
        value
            .map(|url| normalize_registry_url(registry, url))
            .transpose()
            .map(|value| value.unwrap_or_else(|| "default".to_string()))
    };
    match target {
        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
        PublishTarget::Npm { registry, access } => Ok(format!(
            ";target=npm:{}:{access:?}",
            endpoint("npm", registry.as_ref())?
        )),
        PublishTarget::Pypi { index } => Ok(format!(";target=pypi:{}", endpoint("pypi", index.as_ref())?)),
        PublishTarget::NuGet { source } => Ok(format!(";target=nuget:{}", endpoint("nuget", source.as_ref())?)),
        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
        PublishTarget::None => Ok(";target=none".to_string()),
        #[allow(unreachable_patterns)]
        _ => Ok(";target=future".to_string()),
    }
}

/// Normalizes only scheme, authority (including explicit port), and path.
/// Userinfo, queries, and fragments are rejected before they can influence a
/// durable binding fingerprint.
fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
        registry: registry.to_string(),
        reason: "missing scheme",
    })?;
    if scheme.is_empty() || remainder.is_empty() {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "empty scheme or authority",
        });
    }
    if remainder.contains('@') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "userinfo is forbidden",
        });
    }
    if remainder.contains('?') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "query string is forbidden",
        });
    }
    if remainder.contains('#') {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "fragment is forbidden",
        });
    }
    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
    if authority.is_empty() || authority.chars().any(char::is_whitespace) {
        return Err(GraphError::UnsafeRegistryBinding {
            registry: registry.to_string(),
            reason: "invalid authority",
        });
    }
    let suffix = if path.is_empty() {
        String::new()
    } else {
        format!("/{path}")
    };
    Ok(format!(
        "{}://{}{}",
        scheme.to_ascii_lowercase(),
        authority.to_ascii_lowercase(),
        suffix
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::Path;

    use callisto_model::{CommandError, CommandOutput, CommandRunner, Ecosystem, VersionGrammar};

    use crate::IgnoreWalkLocator;

    struct RealGitRunner;

    impl CommandRunner for RealGitRunner {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            let output = std::process::Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }
    }

    fn workspace() -> (tempfile::TempDir, RealGitRunner) {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.3\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(
            dir.path().join("callisto.toml"),
            "[[package]]\nmatch = \"release-fixture\"\npublish-to = [\"crates-io\"]\n",
        )
        .unwrap();
        (dir, RealGitRunner)
    }

    fn selection() -> ReleaseSelection {
        ReleaseSelection::new(BTreeMap::from([(
            ReleasePackageId::new(Ecosystem::Cargo, "release-fixture").unwrap(),
            Version::parse("1.2.3", VersionGrammar::SemVer).unwrap(),
        )]))
    }

    fn source() -> SourceIdentity {
        SourceIdentity::git_commit("a".repeat(40)).unwrap()
    }

    fn git_init_with_commit(root: &Path) {
        for args in [
            ["init", "-q"].as_slice(),
            ["config", "user.email", "test@example.com"].as_slice(),
            ["config", "user.name", "Test"].as_slice(),
            ["config", "commit.gpgsign", "false"].as_slice(),
            ["add", "."].as_slice(),
            ["commit", "-q", "-m", "fixture"].as_slice(),
            ["checkout", "--detach", "-q", "HEAD"].as_slice(),
        ] {
            let output = std::process::Command::new("git")
                .args(args)
                .current_dir(root)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }
    }

    #[test]
    fn registry_binding_rejects_credential_bearing_or_ambiguous_urls() {
        for value in [
            "https://token@registry.example.test/index",
            "https://registry.example.test/index?token=secret",
            "https://registry.example.test/index#fragment",
        ] {
            assert!(
                normalize_registry_url("test", value).is_err(),
                "{value} must be rejected"
            );
        }
        assert_eq!(
            normalize_registry_url("test", "HTTPS://Registry.Example.Test:443/index").unwrap(),
            "https://registry.example.test:443/index"
        );
    }

    #[test]
    fn selection_is_data_not_a_planner_seam() {
        let id = ReleasePackageId::new(Ecosystem::Cargo, "example").unwrap();
        let version = Version::parse("1.2.3", callisto_model::VersionGrammar::SemVer).unwrap();
        let selection = ReleaseSelection::new(BTreeMap::from([(id.clone(), version.clone())]));
        assert_eq!(selection.versions().get(&id), Some(&version));
    }

    #[test]
    fn validation_accepts_same_workspace_and_rejects_stale_manifest_snapshot() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let selection = selection();
        let source = SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha().unwrap(),
        };
        let intent = build_release_intent(&ws, &selection, source, ExecutionTrustProfileV1::GitCommit).unwrap();
        let validated =
            validate_release_intent(&ws, &selection, intent.clone()).expect("unchanged workspace validates");
        assert_eq!(validated.intent().digest(), intent.digest());

        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.4\"\nedition = \"2021\"\n",
        )
        .unwrap();
        let err = validate_release_intent(&ws, &selection, intent).expect_err("manifest bytes changed after approval");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }

    #[test]
    fn validation_rejects_changed_selection_and_derived_dag() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let source = SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha().unwrap(),
        };
        let intent = build_release_intent(&ws, &selection(), source, ExecutionTrustProfileV1::GitCommit).unwrap();
        let changed = ReleaseSelection::new(BTreeMap::from([(
            ReleasePackageId::new(Ecosystem::Cargo, "release-fixture").unwrap(),
            Version::parse("1.2.4", VersionGrammar::SemVer).unwrap(),
        )]));
        let err = validate_release_intent(&ws, &changed, intent)
            .expect_err("a different selected version derives a different DAG");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }

    #[test]
    fn construction_rejects_a_source_identity_that_does_not_match_head() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let attacker_source = source();
        let err = build_release_intent(&ws, &selection(), attacker_source, ExecutionTrustProfileV1::GitCommit)
            .expect_err("supplied SHA must be checked against HEAD during construction");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }
}
