#[cfg(test)]
mod tests {
    use super::*;
    use std::path::Path;

    use callisto_model::{CommandError, CommandOutput, CommandRunner, Ecosystem, VersionGrammar};

    use crate::IgnoreWalkLocator;

    struct RealGitRunner;

    impl CommandRunner for RealGitRunner {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            let output = std::process::Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }
    }

    fn workspace() -> (tempfile::TempDir, RealGitRunner) {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.3\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(
            dir.path().join("callisto.toml"),
            "[[package]]\nmatch = \"release-fixture\"\npublish-to = [\"crates-io\"]\n",
        )
        .unwrap();
        (dir, RealGitRunner)
    }

    fn selection() -> ReleaseSelection {
        ReleaseSelection::new(BTreeMap::from([(
            ReleasePackageId::new(Ecosystem::Cargo, "release-fixture").unwrap(),
            Version::parse("1.2.3", VersionGrammar::SemVer).unwrap(),
        )]))
    }

    fn source() -> SourceIdentity {
        SourceIdentity::git_commit("a".repeat(40)).unwrap()
    }

    fn git_init_with_commit(root: &Path) {
        for args in [
            ["init", "-q"].as_slice(),
            ["config", "user.email", "test@example.com"].as_slice(),
            ["config", "user.name", "Test"].as_slice(),
            ["config", "commit.gpgsign", "false"].as_slice(),
            ["add", "."].as_slice(),
            ["commit", "-q", "-m", "fixture"].as_slice(),
            ["checkout", "--detach", "-q", "HEAD"].as_slice(),
        ] {
            let output = std::process::Command::new("git")
                .args(args)
                .current_dir(root)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }
    }

    #[test]
    fn registry_binding_rejects_credential_bearing_or_ambiguous_urls() {
        for value in [
            "https://token@registry.example.test/index",
            "https://registry.example.test/index?token=secret",
            "https://registry.example.test/index#fragment",
        ] {
            assert!(
                normalize_registry_url("test", value).is_err(),
                "{value} must be rejected"
            );
        }
        assert_eq!(
            normalize_registry_url("test", "HTTPS://Registry.Example.Test:443/index").unwrap(),
            "https://registry.example.test:443/index"
        );
    }

    #[test]
    fn selection_is_data_not_a_planner_seam() {
        let id = ReleasePackageId::new(Ecosystem::Cargo, "example").unwrap();
        let version = Version::parse("1.2.3", callisto_model::VersionGrammar::SemVer).unwrap();
        let selection = ReleaseSelection::new(BTreeMap::from([(id.clone(), version.clone())]));
        assert_eq!(selection.versions().get(&id), Some(&version));
    }

    #[test]
    fn validation_accepts_same_workspace_and_rejects_stale_manifest_snapshot() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let selection = selection();
        let source = SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha().unwrap(),
        };
        let intent = build_release_intent(&ws, &selection, source, ExecutionTrustProfileV1::GitCommit).unwrap();
        let validated =
            validate_release_intent(&ws, &selection, intent.clone()).expect("unchanged workspace validates");
        assert_eq!(validated.intent().digest(), intent.digest());

        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.4\"\nedition = \"2021\"\n",
        )
        .unwrap();
        let err = validate_release_intent(&ws, &selection, intent).expect_err("manifest bytes changed after approval");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }

    #[test]
    fn validation_rejects_changed_selection_and_derived_dag() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let source = SourceIdentity::GitCommit {
            sha: ws.git_access().head_sha().unwrap(),
        };
        let intent = build_release_intent(&ws, &selection(), source, ExecutionTrustProfileV1::GitCommit).unwrap();
        let changed = ReleaseSelection::new(BTreeMap::from([(
            ReleasePackageId::new(Ecosystem::Cargo, "release-fixture").unwrap(),
            Version::parse("1.2.4", VersionGrammar::SemVer).unwrap(),
        )]));
        let err = validate_release_intent(&ws, &changed, intent)
            .expect_err("a different selected version derives a different DAG");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }

    #[test]
    fn construction_rejects_a_source_identity_that_does_not_match_head() {
        let (dir, runner) = workspace();
        git_init_with_commit(dir.path());
        let locator = IgnoreWalkLocator::new(dir.path());
        let ws = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
        let attacker_source = source();
        let err = build_release_intent(&ws, &selection(), attacker_source, ExecutionTrustProfileV1::GitCommit)
            .expect_err("supplied SHA must be checked against HEAD during construction");
        assert!(matches!(err, GraphError::ReleaseIntentStale));
    }
