  1	//! Graph-owned construction and validation of durable release intents.
  2	//!
  3	//! The caller supplies an already-resolved selection.  This deliberately does
  4	//! not call `plan_version` or `plan_publish`: received-intent validation must
  5	//! compare an approval, not silently make a fresh planning decision.
  6	
  7	use std::collections::{BTreeMap, BTreeSet};
  8	
