 18	/// Exact package/version values selected by a preceding release decision.
 19	#[derive(Clone, Debug, Default, PartialEq, Eq)]
 20	pub struct ReleaseSelection {
 21	    versions: BTreeMap<ReleasePackageId, Version>,
 22	}
 23	
 24	impl ReleaseSelection {
 25	    pub fn new(versions: BTreeMap<ReleasePackageId, Version>) -> Self {
 26	        Self { versions }
 27	    }
 28	
 29	    pub fn versions(&self) -> &BTreeMap<ReleasePackageId, Version> {
 30	        &self.versions
 31	    }
 32	}
