236	fn push_component(
237	    components: &mut Vec<ReleaseInputComponentV1>,
238	    kinds: &mut BTreeSet<String>,
239	    kind: impl Into<String>,
240	    value: String,
241	) {
242	    let kind = kind.into();
243	    assert!(
244	        kinds.insert(kind.clone()),
245	        "release snapshot component kinds must be unique"
246	    );
247	    components.push(ReleaseInputComponentV1 {
248	        kind,
249	        fingerprint: digest_text("component", &value),
250	    });
251	}
252	
253	fn push_fingerprint(
254	    components: &mut Vec<ReleaseInputComponentV1>,
255	    kinds: &mut BTreeSet<String>,
256	    kind: impl Into<String>,
257	    fingerprint: SemanticInputDigest,
258	) {
259	    let kind = kind.into();
260	    assert!(
261	        kinds.insert(kind.clone()),
262	        "release snapshot component kinds must be unique"
263	    );
264	    components.push(ReleaseInputComponentV1 { kind, fingerprint });
265	}
266	
267	fn digest_text(tag: &str, text: &str) -> SemanticInputDigest {
268	    let mut transcript = CanonicalTranscript::semantic_input_v1();
269	    transcript.push_str(tag, text);
270	    SemanticInputDigest::from_transcript(&transcript)
271	}
272	
273	fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
274	    let mut transcript = CanonicalTranscript::semantic_input_v1();
275	    transcript.push_bytes(tag, bytes);
276	    SemanticInputDigest::from_transcript(&transcript)
277	}
278	
279	fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
280	    let endpoint = |registry, value: Option<&String>| {
281	        value
282	            .map(|url| normalize_registry_url(registry, url))
283	            .transpose()
284	            .map(|value| value.unwrap_or_else(|| "default".to_string()))
285	    };
286	    match target {
287	        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
288	        PublishTarget::Npm { registry, access } => Ok(format!(
289	            ";target=npm:{}:{access:?}",
290	            endpoint("npm", registry.as_ref())?
291	        )),
292	        PublishTarget::Pypi { index } => Ok(format!(";target=pypi:{}", endpoint("pypi", index.as_ref())?)),
293	        PublishTarget::NuGet { source } => Ok(format!(";target=nuget:{}", endpoint("nuget", source.as_ref())?)),
294	        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
295	        PublishTarget::None => Ok(";target=none".to_string()),
296	        #[allow(unreachable_patterns)]
297	        _ => Ok(";target=future".to_string()),
298	    }
299	}
300	
301	/// Normalizes only scheme, authority (including explicit port), and path.
302	/// Userinfo, queries, and fragments are rejected before they can influence a
303	/// durable binding fingerprint.
304	fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
305	    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
306	        registry: registry.to_string(),
307	        reason: "missing scheme",
308	    })?;
309	    if scheme.is_empty() || remainder.is_empty() {
310	        return Err(GraphError::UnsafeRegistryBinding {
311	            registry: registry.to_string(),
312	            reason: "empty scheme or authority",
313	        });
314	    }
315	    if remainder.contains('@') {
316	        return Err(GraphError::UnsafeRegistryBinding {
317	            registry: registry.to_string(),
318	            reason: "userinfo is forbidden",
319	        });
320	    }
321	    if remainder.contains('?') {
322	        return Err(GraphError::UnsafeRegistryBinding {
323	            registry: registry.to_string(),
324	            reason: "query string is forbidden",
325	        });
326	    }
327	    if remainder.contains('#') {
328	        return Err(GraphError::UnsafeRegistryBinding {
329	            registry: registry.to_string(),
330	            reason: "fragment is forbidden",
331	        });
332	    }
333	    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
334	    if authority.is_empty() || authority.chars().any(char::is_whitespace) {
335	        return Err(GraphError::UnsafeRegistryBinding {
336	            registry: registry.to_string(),
337	            reason: "invalid authority",
338	        });
339	    }
340	    let suffix = if path.is_empty() {
341	        String::new()
342	    } else {
343	        format!("/{path}")
344	    };
345	    Ok(format!(
346	        "{}://{}{}",
347	        scheme.to_ascii_lowercase(),
348	        authority.to_ascii_lowercase(),
349	        suffix
350	    ))
351	}
