 49	/// Builds a canonical intent using read-only workspace observation only.
 50	pub fn build_release_intent<R: CommandRunner, D: DependencyResolver>(
 51	    ws: &Workspace<'_, R, D>,
 52	    selection: &ReleaseSelection,
 53	    source: SourceIdentity,
 54	    trust_profile: ExecutionTrustProfileV1,
 55	) -> Result<ReleaseIntentV1, GraphError> {
 56	    match trust_profile {
 57	        ExecutionTrustProfileV1::GitCommit => {
 58	            let git = ws.git_access();
 59	            if !git.has_clean_detached_head()? || source != (SourceIdentity::GitCommit { sha: git.head_sha()? }) {
 60	                return Err(GraphError::ReleaseIntentStale);
 61	            }
 62	        }
 63	        // A hermetic release needs a closed-root observer. It is safer to
 64	        // reject this profile until graph owns that complete observation than
 65	        // to accidentally bless a Git-derived projection as hermetic.
 66	        ExecutionTrustProfileV1::HermeticContent => return Err(GraphError::ReleaseIntentStale),
 67	    }
 68	    let (snapshot, operations) = derive_release_inputs(ws, selection, source)?;
 69	    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)
 70	}
