267	fn digest_text(tag: &str, text: &str) -> SemanticInputDigest {
268	    let mut transcript = CanonicalTranscript::semantic_input_v1();
269	    transcript.push_str(tag, text);
270	    SemanticInputDigest::from_transcript(&transcript)
271	}
