273	fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
274	    let mut transcript = CanonicalTranscript::semantic_input_v1();
275	    transcript.push_bytes(tag, bytes);
276	    SemanticInputDigest::from_transcript(&transcript)
