279	fn target_fingerprint(target: &PublishTarget) -> Result<String, GraphError> {
280	    let endpoint = |registry, value: Option<&String>| {
281	        value
282	            .map(|url| normalize_registry_url(registry, url))
283	            .transpose()
284	            .map(|value| value.unwrap_or_else(|| "default".to_string()))
285	    };
286	    match target {
287	        PublishTarget::CratesIo => Ok(";target=crates-io".to_string()),
288	        PublishTarget::Npm { registry, access } => Ok(format!(
289	            ";target=npm:{}:{access:?}",
290	            endpoint("npm", registry.as_ref())?
291	        )),
292	        PublishTarget::Pypi { index } => Ok(format!(";target=pypi:{}", endpoint("pypi", index.as_ref())?)),
293	        PublishTarget::NuGet { source } => Ok(format!(";target=nuget:{}", endpoint("nuget", source.as_ref())?)),
294	        PublishTarget::GitHubRelease => Ok(";target=github-release".to_string()),
295	        PublishTarget::None => Ok(";target=none".to_string()),
296	        #[allow(unreachable_patterns)]
297	        _ => Ok(";target=future".to_string()),
298	    }
299	}
