301	/// Normalizes only scheme, authority (including explicit port), and path.
302	/// Userinfo, queries, and fragments are rejected before they can influence a
303	/// durable binding fingerprint.
304	fn normalize_registry_url(registry: &str, raw: &str) -> Result<String, GraphError> {
305	    let (scheme, remainder) = raw.split_once("://").ok_or_else(|| GraphError::UnsafeRegistryBinding {
306	        registry: registry.to_string(),
307	        reason: "missing scheme",
308	    })?;
309	    if scheme.is_empty() || remainder.is_empty() {
310	        return Err(GraphError::UnsafeRegistryBinding {
311	            registry: registry.to_string(),
312	            reason: "empty scheme or authority",
313	        });
314	    }
315	    if remainder.contains('@') {
316	        return Err(GraphError::UnsafeRegistryBinding {
317	            registry: registry.to_string(),
318	            reason: "userinfo is forbidden",
319	        });
320	    }
321	    if remainder.contains('?') {
322	        return Err(GraphError::UnsafeRegistryBinding {
323	            registry: registry.to_string(),
324	            reason: "query string is forbidden",
325	        });
326	    }
327	    if remainder.contains('#') {
328	        return Err(GraphError::UnsafeRegistryBinding {
329	            registry: registry.to_string(),
330	            reason: "fragment is forbidden",
331	        });
332	    }
333	    let (authority, path) = remainder.split_once('/').unwrap_or((remainder, ""));
334	    if authority.is_empty() || authority.chars().any(char::is_whitespace) {
335	        return Err(GraphError::UnsafeRegistryBinding {
336	            registry: registry.to_string(),
337	            reason: "invalid authority",
338	        });
339	    }
340	    let suffix = if path.is_empty() {
341	        String::new()
342	    } else {
343	        format!("/{path}")
344	    };
345	    Ok(format!(
346	        "{}://{}{}",
347	        scheme.to_ascii_lowercase(),
348	        authority.to_ascii_lowercase(),
349	        suffix
350	    ))
351	}
