583	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
584	    where
585	        D: Deserializer<'de>,
586	    {
587	        let wire = ReleaseIntentV1Wire::deserialize(deserializer)?;
588	        if wire.schema_version != Self::SCHEMA_VERSION
589	            || wire.snapshot.schema_version != ReleaseInputSnapshotV1::SCHEMA_VERSION
590	        {
591	            return Err(serde::de::Error::custom("unsupported release intent schema version"));
592	        }
593	        if wire.snapshot.components.windows(2).any(|pair| pair[0] >= pair[1]) {
594	            return Err(serde::de::Error::custom("release input components are not canonical"));
595	        }
596	        let intent = Self::new(wire.snapshot, wire.trust_profile, wire.operations).map_err(serde::de::Error::custom)?;
597	        if intent.digest != wire.digest {
598	            return Err(serde::de::Error::custom(
599	                "release intent digest does not match canonical content",
600	            ));
601	        }
602	        Ok(intent)
603	    }
604	}
