 50	    /// Returns whether this checkout is detached and has no tracked or
 51	    /// non-ignored untracked changes. Durable release authorization uses the
 52	    /// shell backend deliberately: its porcelain output is Git's canonical
 53	    /// definition of worktree cleanliness and is available on every target.
 54	    pub fn has_clean_detached_head(&self) -> Result<bool, VcsError> {
 55	        self.shell.has_clean_detached_head()
 56	    }
 57	}
