 10	/// Selects between native `gix` ([`GitRepository`]) and a `CommandRunner`
 11	/// shell-out ([`ShellGit`]) per operation, so callers never branch on it.
 12	///
 13	/// Construct via [`GitAccess::discover`], then call [`GitDataSource`]
 14	/// methods directly.
 15	///
 16	/// **Fallback policy differs by operation category, deliberately:**
 17	///
 18	/// - **Reads** ([`GitDataSource::list_tags`], [`GitDataSource::resolve_commit`],
 19	///   [`GitDataSource::commits_since`]): fall back to shell on *any* `gix`
 20	///   error (failed discovery, or a discovered repo's op failing) --
 21	///   retrying a read can only help.
 22	/// - **Writes** ([`GitDataSource::create_tag`], [`GitDataSource::create_floating_major`]):
 23	///   fall back *only* if `gix` was never discovered. A discovered repo's
 24	///   result is authoritative -- retrying a failed mutation through a
 25	///   different path risks masking a real failure, or double-applying a
 26	///   partial mutation.
 27	pub struct GitAccess<'r> {
 28	    native: Option<GitRepository>,
 29	    shell: ShellGit<'r>,
 30	}
 31	
 32	impl<'r> GitAccess<'r> {
 33	    /// Tries to discover a native `gix` repository at `root`; regardless of
 34	    /// whether that succeeds, also prepares the `CommandRunner`-shelled
 35	    /// backend against the same `root`, ready to serve as a fallback (reads)
 36	    /// or as the sole backend (writes, when discovery failed).
 37	    ///
 38	    /// Never fails: a discovery failure just means every operation runs
 39	    /// through the shell backend instead, exactly as it unconditionally
 40	    /// does on `wasm32` (gix is excluded from that target's dependency set,
 41	    /// so [`GitRepository::discover`] always returns `Err` there).
 42	    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
 43	        let root = root.as_ref();
 44	        GitAccess {
 45	            native: GitRepository::discover(root).ok(),
 46	            shell: ShellGit::new(runner, root.to_path_buf()),
 47	        }
 48	    }
