630	fn digest_intent(
631	    snapshot: &ReleaseInputSnapshotV1,
632	    trust_profile: ExecutionTrustProfileV1,
633	    operations: &[ReleaseOperation],
634	) -> IntentDigest {
635	    let mut transcript = CanonicalTranscript::intent_v1();
636	    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
637	    transcript.push_str("snapshot", snapshot.digest().as_str());
638	    transcript.push_str(
639	        "trust-profile",
640	        match trust_profile {
641	            ExecutionTrustProfileV1::GitCommit => "git-commit",
642	            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
643	        },
644	    );
645	    for operation in operations {
646	        transcript.push_str("operation", &operation_id_text(&operation.id));
647	        for prerequisite in &operation.prerequisites {
648	            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
649	        }
650	    }
651	    IntentDigest::from_transcript(&transcript)
652	}
653	
654	fn operation_id_text(id: &ReleaseOperationId) -> String {
655	    let role = match &id.role {
656	        ReleaseOperationRole::RegistryPublish { registry_key } => format!("publish:{}", registry_key.as_str()),
657	        ReleaseOperationRole::Tag => "tag".to_string(),
658	        ReleaseOperationRole::ForgeRelease => "forge-release".to_string(),
659	    };
660	    format!("{}|{}|{}", id.package, role, id.version.render())
661	}
662	
663	fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
664	    if operations.windows(2).any(|pair| pair[0].id >= pair[1].id) {
665	        if operations.windows(2).any(|pair| pair[0].id == pair[1].id) {
666	            return Err(ReleaseIntentError::DuplicateOperation {
667	                id: Box::new(
668	                    operations
669	                        .windows(2)
670	                        .find(|pair| pair[0].id == pair[1].id)
671	                        .expect("duplicate window exists")[0]
672	                        .id
673	                        .clone(),
674	                ),
675	            });
676	        }
677	        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
678	    }
679	    let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
680	    for operation in operations {
681	        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
682	            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
683	                id: Box::new(operation.id.clone()),
684	            });
685	        }
686	        for prerequisite in &operation.prerequisites {
687	            if prerequisite == &operation.id {
688	                return Err(ReleaseIntentError::SelfPrerequisite {
689	                    id: Box::new(operation.id.clone()),
690	                });
691	            }
692	            if !ids.contains(prerequisite) {
693	                return Err(ReleaseIntentError::UnknownPrerequisite {
694	                    id: Box::new(operation.id.clone()),
695	                    prerequisite: Box::new(prerequisite.clone()),
696	                });
697	            }
698	        }
699	    }
700	    let edges: BTreeMap<_, _> = operations
701	        .iter()
702	        .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
703	        .collect();
704	    let mut visiting = BTreeSet::new();
705	    let mut visited = BTreeSet::new();
706	    for id in edges.keys() {
707	        if visit(id, &edges, &mut visiting, &mut visited) {
708	            return Err(ReleaseIntentError::Cycle {
709	                id: Box::new(id.clone()),
710	            });
711	        }
712	    }
713	    Ok(())
714	}
715	
716	fn visit(
717	    id: &ReleaseOperationId,
718	    edges: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
719	    visiting: &mut BTreeSet<ReleaseOperationId>,
720	    visited: &mut BTreeSet<ReleaseOperationId>,
721	) -> bool {
722	    if visited.contains(id) {
723	        return false;
724	    }
725	    if !visiting.insert(id.clone()) {
726	        return true;
727	    }
728	    let has_cycle = edges.get(id).is_some_and(|prerequisites| {
729	        prerequisites
730	            .iter()
731	            .any(|prerequisite| visit(prerequisite, edges, visiting, visited))
732	    });
733	    visiting.remove(id);
734	    visited.insert(id.clone());
735	    has_cycle
736	}
