 90	/// correctness risk for release tagging).
 91	fn compile_glob(glob: &str) -> Result<globset::GlobMatcher, VcsError> {
 92	    globset::Glob::new(glob)
 93	        .map(|g| g.compile_matcher())
 94	        .map_err(|e| VcsError::InvalidGlob {
 95	            pattern: glob.to_string(),
 96	            message: e.to_string(),
