   875	    pub fn from_state(state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
   876	        let mut outcomes = BTreeMap::new();
   877	        for (id, operation_state) in &state.operations {
   878	            let outcome = match operation_state {
   879	                OperationState::Published => OperationOutcome::Published,
   880	                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
   881	                OperationState::Failed => OperationOutcome::Failed,
   882	                OperationState::Blocked => OperationOutcome::Blocked,
   883	                OperationState::Pending | OperationState::Attempting => {
