   863	/// A terminal receipt derived only from a complete execution state.
   864	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
   865	#[serde(rename_all = "camelCase", deny_unknown_fields)]
   866	pub struct ReleaseReceiptV1 {
